-- P03 · Estado do staging que a v1.0.1 tem de encontrar (e preservar).
-- Qualquer FALHA => PARAR e rever COLLISIONS.md. GUARDAR o valor obtido de P03-15 para o Q04.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH pf AS (SELECT p.oid, p.proname::text AS nome, p.pronargs, p.prosrc, p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'P03-01'::text, 'funções em public = has_role, has_staging_access'::text, (coalesce((SELECT array_agg(nome ORDER BY nome COLLATE "C") FROM pf), '{}') = ARRAY['has_role', 'has_staging_access'])::boolean, 'has_role,has_staging_access'::text, ((SELECT string_agg(nome, ',' ORDER BY nome COLLATE "C") FROM pf))::text
  UNION ALL SELECT 'P03-02'::text, 'has_role: corpo da migração 0000 do staging'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role') = '6b9bca1cc09de70841cac113efbdd41a')::boolean, '6b9bca1cc09de70841cac113efbdd41a'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role'))::text
  UNION ALL SELECT 'P03-03'::text, 'has_staging_access: corpo da migração 0000 do staging'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access') = '4376edeea92abf14230207df0fbbef11')::boolean, '4376edeea92abf14230207df0fbbef11'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access'))::text
  UNION ALL SELECT 'P03-04'::text, 'has_role/has_staging_access: anon sem EXECUTE, authenticated com EXECUTE'::text, ((SELECT bool_and(NOT has_function_privilege('anon', oid, 'EXECUTE') AND has_function_privilege('authenticated', oid, 'EXECUTE')) FROM pf) AND (SELECT count(*) FROM pf) = 2)::boolean, 'sim'::text, ((SELECT string_agg(nome || ':anon=' || has_function_privilege('anon', oid, 'EXECUTE')::text || ',auth=' || has_function_privilege('authenticated', oid, 'EXECUTE')::text, ' ' ORDER BY nome) FROM pf))::text
  UNION ALL SELECT 'P03-05'::text, 'tipos enum em public = app_role'::text, (coalesce((SELECT array_agg(t.typname::text ORDER BY t.typname) FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typtype = 'e'), '{}') = ARRAY['app_role'])::boolean, 'app_role'::text, ((SELECT string_agg(t.typname::text, ',') FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typtype = 'e'))::text
  UNION ALL SELECT 'P03-06'::text, 'valores de app_role = admin,tester'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role') = 'admin,tester')::boolean, 'admin,tester'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role'))::text
  UNION ALL SELECT 'P03-07'::text, 'colunas de user_roles = id,user_id,role,created_at'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped) = 'id,user_id,role,created_at')::boolean, 'id,user_id,role,created_at'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped))::text
  UNION ALL SELECT 'P03-08'::text, 'restrições de user_roles'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n') = 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key')::boolean, 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n'))::text
  UNION ALL SELECT 'P03-09'::text, 'políticas em public = as 2 do staging'::text, (coalesce((SELECT array_agg(tablename::text || '.' || policyname::text ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public'), '{}') = ARRAY['staging_notes.Staging members read notes', 'user_roles.Users read own roles'])::boolean, 'staging_notes.Staging members read notes,user_roles.Users read own roles'::text, ((SELECT string_agg(tablename::text || '.' || policyname::text, ',' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public'))::text
  UNION ALL SELECT 'P03-10'::text, 'nenhum gatilho em auth.users'::text, (NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'auth.users'::regclass AND NOT tgisinternal))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(tgname::text, ',') FROM pg_trigger WHERE tgrelid = 'auth.users'::regclass AND NOT tgisinternal), 'nenhum'))::text
  UNION ALL SELECT 'P03-11'::text, 'nenhum gatilho em public'::text, (NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND NOT t.tgisinternal))::boolean, 'nenhum'::text, ((SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND NOT t.tgisinternal)::text)::text
  UNION ALL SELECT 'P03-12'::text, 'schema extensions existe'::text, (EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions'))::boolean, 'sim'::text, (CASE WHEN EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions') THEN 'sim' ELSE 'não' END)::text
  UNION ALL SELECT 'P03-13'::text, 'staging_notes: as 3 notas da migração 0000'::text, ((SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes) = '9839c85692f965b4f419fb33c6af3404' AND (SELECT count(*) FROM public.staging_notes) = 3)::boolean, '3 / 9839c85692f965b4f419fb33c6af3404'::text, ((SELECT count(*) FROM public.staging_notes)::text || ' / ' || (SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes))::text
  UNION ALL SELECT 'P03-14'::text, 'user_roles sem papéis V2 (consultant/support_admin/super_admin)'::text, (NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin')))::boolean, 'nenhum'::text, ((SELECT count(*) FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin'))::text)::text
  UNION ALL SELECT 'P03-15'::text, 'impressão das permissões de staging_notes/user_roles/has_role/has_staging_access (GUARDAR para Q04)'::text, (md5(coalesce((SELECT string_agg(c.relname::text || '=' || coalesce(c.relacl::text, 'NULL'), ';' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), '') || '|' || coalesce((SELECT string_agg(p.proname::text || '=' || coalesce(p.proacl::text, 'NULL'), ';' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), '')) ~ '^[0-9a-f]{32}$')::boolean, 'md5'::text, (md5(coalesce((SELECT string_agg(c.relname::text || '=' || coalesce(c.relacl::text, 'NULL'), ';' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), '') || '|' || coalesce((SELECT string_agg(p.proname::text || '=' || coalesce(p.proacl::text, 'NULL'), ';' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), '')))::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 15 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
